/**
 * Offline multilingual phrasebook.
 *
 * ORCA has two synthesis paths:
 *
 *  1. **Gemini** (when `GEMINI_API_KEY` is configured) writes a free-form,
 *     fully natural answer in the detected language.
 *  2. **This phrasebook** (always available) composes a structured brief from
 *     slot templates. It is deliberately slot-driven: the numbers, units,
 *     coordinates and species names are language-neutral, so a fisherman gets
 *     readable prose in their own language while the technical evidence stays
 *     unambiguous.
 *
 * Every language entry is complete — there are no English fallbacks mid-entry —
 * so the offline path is a genuine first-class experience rather than a stub.
 */

import { LanguageCode, ProductivityClass, RiskLevel, TidalData } from '../types';
import { describeSeaState } from './dataset';

