export interface Phrasebook {
  locale: LanguageCode;
  intro: string;
  disclaimer: string;
  /**
   * Replacement fragment the safety critic substitutes for over-promising
   * phrases. It has to be in the fisher's own language: it is spliced into the
   * middle of a sentence they are about to act on.
   */
  calibrated: string;
  labels: PhrasebookLabels;
  /** Static UI chrome for the shell and every screen. */
  ui: UiStrings;
  /** Douglas sea-state 0-8 descriptors, shortest form. */
  seaStates: string[];
  /** Risk level names, indexed by RISK_ORDER. */
  riskWords: [string, string, string, string];
  trendWords: [string, string, string];
   /**
    * Translated display name and handling note per vessel profile id. Both are
    * ORCA's own descriptive copy rather than quoted authority text, so unlike a
    * bulletin they are translated. They are interpolated into the vessel-fit
    * sentence (peak wind of X kt exceeds the Y kt limit for a <name>, then the
    * note) which is the line a fisher reads to decide whether to go out, so an
    * English name there made the sentence unusable in every language but
    * English. Keyed by id so a new profile is added in one place; vesselName()
    * falls back to the dataset label if an id is ever missing.
    */
   vesselProfiles: Record<string, { label: string; note: string }>;
  productivityWords: [string, string, string, string];
  horizon: [string, string, string, string, string];
  headlines: {
    pfz: string;
    safety: string;
    tide: string;
    alerts: string;
    hotspots: string;
    route: string;
    productivity: string;
    avoid: string;
    ocean: string;
    weather: string;
    geofence: string;
    generic: string;
    noAlerts: string;
  };
  recommendations: {
    safe: string;
    caution: string;
    unsafe: string;
    pfz: string;
    generic: string;
  };
  questions: string[];
  evidenceKeys: {
    waveHeight: string;
    windSpeed: string;
    gusts: string;
    sst: string;
    chlorophyll: string;
    productivity: string;
    highTide: string;
    lowTide: string;
    tideRange: string;
    bearing: string;
    depth: string;
    species: string;
    riskLevel: string;
    vessel: string;
    eta: string;
    safetyScore: string;
    distanceFromPort: string;
    keepClear: string;
    insideBoundary: string;
    rain: string;
    radius: string;
  };
  /** Structured alert copy — rendered per language from `params`. */
  alerts: {
    windowFrom: string;
    sourceWeather: string;
    sourceConvective: string;
    sourceMarine: string;
    strongWind: { title: string; description: string; action: string };
    squall: { title: string; description: string; action: string };
    lightning: { title: string; description: string; action: string };
    highWave: { title: string; description: string; action: string };
    roughSea: { title: string; description: string; action: string };
    cyclone: { title: string; actionOrange: string; actionOther: string };
  };
  /** Weather-condition phrases keyed from the WMO-condition map. */
  conditions: {
    clear: string;
    partlyCloudy: string;
    overcast: string;
    fog: string;
    lightRain: string;
    rain: string;
    snow: string;
    snowShowers: string;
    showers: string;
    thunder: string;
    thunderHail: string;
    variable: string;
  };
  /** Data-product attribution chips — product tokens stay, roles localize. */
  productSources: {
    weather: string;
    ocean: string;
    pfz: string;
    hotspots: string;
    alerts: string;
    historical: string;
    disasters: string;
    reference: string;
  };
  /** Short evidence-source names. */
  sourceWords: {
    geodesicEngine: string;
    coastalGazetteer: string;
    referencePosition: string;
  };
}

