      infoSafetyBodyWord: 'ORCA નિર્ણય-મદદ પૂરી પાડે છે. તે ક્યારેય સુરક્ષાની ખાતરી આપતું નથી, અને ક્યારેય અધિકૃત સૂચનાનો અસ્વીકાર કરતું નથી. બતાવાતા પહેલાં એક સંકલ્પિત ટીકાતકાર એજન્ટ દરેક જવાબ ફરી વાંચે છે, અતિ-આતમવિશ્વાસવાળા વાક્યો દૂર કરે છે, કોઈપણ ORANGE કે RED સૂચનાને વધારે છે, અને તેને IMD, INCOIS તેમજ બંદર અધિકારીની સૂચનાઓ સાથે જોડે છે. જહાજ અંગે નિર્ણય માલિકનો જ રહે છે.',
