      infoSafetyWord: 'ಸುರಕ್ಷತಾ ಮಾನದಂಡ ಮತ್ತು ಜವಾಬ್ದಾರಿ AI',
      infoSafetyBodyWord: 'ORCA ನಿರ್ಧಾರ ಸಹಾಯ ನೀಡುತ್ತದೆ. ಅದು ಎಂದಿಗೂ ಸುರಕ್ಷತೆಯ ಖಾತರಿ ನೀಡುವುದಿಲ್ಲ, ಮತ್ತು ಎಂದಿಗೂ ಅಧಿಕೃತ ಎಚ್ಚರಿಕೆಯನ್ನು ತಡೆಯುವುದಿಲ್ಲ. ತೋರಿಸುವ ಮೊದಲು ಒಂದು ಮೀಸಲಾತಿ ವಿಮರ್ಶಕ ಏಜೆಂಟ್ ಪ್ರತಿ ಉತ್ತರವನ್ನು ಮತ್ತೆ ಓದುತ್ತದೆ, ಅತಿ ಆತ್ಮವಿಶ್ವಾಸದ ವಾಕ್ಯಗಳನ್ನು ತೆಗೆದುಹಾಕುತ್ತದೆ, ORANGE ಅಥವಾ RED ಎಚ್ಚರಿಕೆಯನ್ನು ಎತ್ತರಿಸುತ್ತದೆ, ಮತ್ತು ಅದರನ್ನು IMD, INCOIS ಮತ್ತು ರಂದು ಅಧಿಕಾರಿಗಳ ಎಚ್ಚರಿಕೆಗಳಿಗೆ ಜೋಡಿಸುತ್ತದೆ. ದೋಣಿಯ ನಿರ್ಧಾರ ಮಾಲಕನದ್ದೇ ಉಳಿಯುತ್ತದೆ.',
      apkTitleWord: 'ORCA ಬಿಲ್ಡ್ ಮತ್ತು ಪ್ರದರ್ಶನ ಕೇಂದ್ರ',
