      apkStep1BodyWord: 'EAS ನೇರ ಸ್ಥಾಪಿಸಬಹುದಾದ APK ಗಾಗಿ ಡೌನ್‌ಲೋಡ್ ಲಿಂಕ್ ಮತ್ತು QR ಕೋಡ್ ಮುದ್ರಿಸುತ್ತದೆ — Android Studio ಬೇಡ, ಸ್ಥಳೀಯ SDK ಬೇಡ, ಪಡೆಯುವ ಫೋನಿನಲ್ಲಿ ಏನೂ ಸಿಲುವಿಸಬೇಕಿಲ್ಲ.',
