      infoBaseHarbourBodyWord: 'GPS സ്ഥാനം നൽകുന്നവരെങ്കിൽ ഓരോ ദേശീയ കണക്കുകൂടുത്തലും ഈ തുറമുഖത്തിലേക്കാണ് ബന്ധിപ്പിച്ചിരിക്കുന്നത്.',
      infoAcceptanceWord: 'അംഗീകാര പരിശോധന',
      infoAcceptanceBodyWord: 'പ്രശ്നം പറഞ്ഞിട്ടുന്ന എട്ട് കഴവുകൾ എല്ലാ {n} ഭാഷകളിലും യഥാർത്ഥ ചോദ്യങ്ങളായി മുൻകൂട്ടിയെടുത്തിരിക്കുന്നു. ഓരോന്നും നിങ്ങൾ ടൈപ്പ് ചെയ്യുന്നതിന് തുല്യമായ അതേ പൈപ്പ്‌ലൈനിലൂടെ കടത്തിച്ചുപോകുന്നു — അതിനാൽ ഏതെങ്കിലും ഒന്നിൽ ടാപ്പ് ചെയ്യുന്നത് ഭാഷാ കണ്ടെത്തൽ, ഇന്റെന്റ് പാർസിംഗ്, ഏജന്റ് തിരഞ്ഞെടുക്കൽ, സംശ്ലേഷണം എന്നിവയുടെ യഥാർത്ഥ പരീക്ഷയാണ്, ക്രമീകരിച്ച ഉത്തരമല്ല.',
      infoOpenChatWord: '{lang} എന്ന ഭാഷയിൽ സംഭാഷണം തുറക്കുക',
      infoSafetyWord: 'സുരക്ഷാ മാനദംഡവും ഉത്തരാധികാരിത്വവും ഹെയുള്ള AI',
      infoSafetyBodyWord: 'ORCA തീരുമാന സഹായം നൽകുന്നു. അത് ഒരിക്കലും സുരക്ഷ ഉറപ്പാക്കുകയില്ല, ഔദ്യോഗിക അറിയിക്കൽ മറക്കുകയും ചെയ്യില്ല. തോരുക്കുന്നതിന് മുമ്പ് ഒരു വിശേഷ വിമർശക ഏജന്റ് ഓരോ ഉത്തരവും വീണ്ടും വായിക്കുകയും, അതികഥിതമായ വാക്കാരങ്ങൾ ഒഴിവാക്കുകയും, ORANGE അല്ലെങ്കിൽ RED അറിയിക്കളെ ഉയരിപ്പിക്കുകയും, അതിനെ IMD, INCOIS, തുറമുഖ അധികൃത അറിയിക്കളുടെ സഹിഞ്ഞായി ചേർക്കുകയും ചെയ്യും. കപ്പലിനെപ്പറ്റിയ തീരുമാനം ഉടമയുടെതന്നെയാണ്.',
      apkTitleWord: 'ORCA ബിൽഡും പ്രദർശന കേന്ദ്രവും',
      apkSubtitleWord: 'ഒരു TypeScript ഏജന്റ് എഞ്ചിൻ · വെബ് ക്ലയന്റ് + Android APK',
      apkTabBuildWord: 'APK ബിൽഡ്',
