      apkTabStructureWord: 'ഫോൾഡർ ഘടന',
      apkTabDemoWord: '3-മിനിറ്റ് ഡെമോ സ്ക്രിപ്റ്റ്',
      apkStep1Word: '1. Expo EAS ക്ലൗഡ് ബിൽഡിലൂടെ സ്വതന്ത്ര APK',
      apkStep1BodyWord: 'നേരിട്ട് ഇൻസ്റ്റാൾ ചെയ്യാവുന്ന APK-യിനായി EAS ഒരു ഡൗൺലോഡ് ലിങ്കും QR കോഡും അച്ചപ്പെടുത്തും — Android Studio വേണ്ട, ലോക്കൽ SDK വേണ്ട, ലഭിക്കുന്ന ഫോണിൽ ഒന്നും ക്രമീകരിക്കേണ്ടതില്ല.',
      apkStep2Word: '2. Expo Go ഉപയോഗിച്ച് യഥാർത്ഥ ഫോണിൽ ഉടൻ പരീക്ഷണം',
      apkStep3Word: '3. APK-യെ ഹോസ്റ്റ് ചെയ്ത എഞ്ചിനോട് ബന്ധിപ്പിക്കുക',
      apkStep3BodyWord: 'വിലാസം കൃത്യമായി ഒരിടത്ത് മാത്രമാണ് ഉള്ളത്, mobile/src/services/api.js, അത് ആദ്യം ഒരു എൻവൈറോൺമെന്റ് വാരിയബിൾ വായിക്കുന്നു:',
      apkStep3Body2Word: 'ബിൽഡ്-ടൈം ലക്ഷ്യത്തിന്, eas.json-ൽ EXPO_PUBLIC_ORCA_API=https://your-host എന്ന് സജ്ജമാക്കുക.',
      apkStep3NoteWord: 'എഞ്ചിൻ ലഭ്യമല്ലെങ്കിൽ ആപ്പ് അത് വ്യക്തമായി പറയും — അത് ഒരിക്കലും കാര്യമായ പ്രവാഹന സൃഷ്ടിക്കില്ല.',
      apkEngineHeadingWord: 'ഏജന്റ് എഞ്ചിൻ ഓടിക്കുക',
      apkEngineKeyNoteWord: 'GEMINI_API_KEY ഐച്ഛികമാണ്. അത് ഇല്ലാത്തവരെയും നിശ്ചിത എഞ്ചിൻ ഓരോ ഉത്തരത്തിനും ആസൂത്രണം ചെയ്യുകയും ചിന്തിക്കുകയും സംശ്ലേഷിക്കുകയും പരിശോധിക്കുകയും ചെയ്യുന്നു.',
