      infoAcceptanceBodyWord: 'సమస్యా వాక్యంలోని ఎనిమిది సామర్థ్యాలు అన్ని {n} భాషల్లోనూ నిజమైన ప్రశ్నలుగా ముందే లోడ్ చేయబడ్డాయి. ప్రతిదాన్నీ మీరు టైప్ చేసేదానికి సమానమైన అదే పైప్‌లైన్ ద్వారా పంపబడతుంది — కాబట్టి ఏదైనా ఒకటి టాప్ చేయడం అనేది భాష గుర్తింపు, ఇంటెంట్ పార్సింగ్, జాబితా ఎంపిక మరియు సంశ్లేషణకు నిజమైన పరీక్ష, స్క్రిప్ట్ చేసిన సమాధానం కాదు.',
      infoOpenChatWord: '{lang} లో సంభాషణ తెరవండి',
      infoSafetyWord: 'భద్రతా ప్రమాణం & జవాబుదారిత్వ AI',
      infoSafetyBodyWord: 'ORCA నిర్ణయ మద్దతును అందిస్తుంది. అది ఎప్పుడూ భద్రతను హామీ ఇవ్వదు, అధికారిక హెచ్చరికను ఎప్పుడూ విరుద్ధించదు. చూపే ముందు ఒక ప్రత్యేక విమర్శక ఏజెంట్ ప్రతి సమాధానాన్ని మళ్లీ చదివి, ఆత్మవిశ్వాసంగా ఉన్న వాక్యాలను తీసివేసి, ఏ ఆరెంజ్ లేదా రెడ్ హెచ్చరికనైనా ఎత్తేము, అలాగే IMD, INCOIS మరియు రేవు అధికారుల హెచ్చరికలతో దాన్ని జోడిస్తుంది. జహాజ్ నిర్ణయం యజమాని వద్దే ఉంటుంది.',
