      apkTabDemoWord: '3-నిమిష డెమో స్క్రిప్ట్',
      apkStep1Word: '1. Expo EAS క్లౌడ్ బిల్డ్‌తో స్టాండ్‌అలోన్ APK',
      apkStep1BodyWord: 'EAS నేరుగా ఇన్‌స్టాల్ చేయగల APK కోసం డౌన్‌లోడ్ లింక్ మరియు QR కోడ్‌ను ముద్రిస్తుంది — Android Studio అవసరం లేదు, లోకల్ SDK అవసరం లేదు, స్వీకరించే ఫోన్‌పై ఏదీ సెట్ చేయాల్సిన అవసరం లేదు.',
