      apkStep3BodyWord: 'చిరునామా ఖచ్చితంగా ఒకే చోట ఉంది, mobile/src/services/api.js, మరియు అది మొదట ఒక ఎన్‌విరాన్‌మెంట్ వేరియబుల్‌ను చదువుతుంది:',
