      infoNoApiKeyWord: 'GEMINI_API_KEY அமைக்கப்படவில்லை. அதிலிருந்தும் ORCA முழுமையாகச் செயல்படுகிறது — விருப்ப மாதிரி திட்டத்தின் காரணத்தையும் பதில் உரையையும் மட்டுமே மீண்டும் எழுதுகிறது, பாதுகாப்பு முக்கியமான முக்கிய எந்திரத்தை ஒருபோதும் சேர்க்கவோ நீக்கவோ முடியாது.',
      infoRosterWord: 'முக்கிய எந்திரப் பட்டியல் ({n})',
      infoRosterBodyWord: 'ஒரு திட்டமைப்பாளர் ஒவ்வொரு கேள்வியையும் பணி வரைபடமாகப் பிரித்து, இந்த நிபுணர்களில் ஒரு பகுதியைத் தேர்ந்தெடுக்கிறார். அவர்கள் ஒரு பொதுப் பலகையில் அமைந்த கணிகளை வெளியிடுகின்றனர், எந்த முக்கிய எந்திரமும் ஒரு துணையிடம் காரணம் கேட்டுக்கொள்ளலாம், மேலும் ஒரு விமர்சனக் கருவி காட்டப்படும் முன் உருவாக்கப்பட்ட பதிலை மதிப்பாய்விற்கு உட்படுத்துகிறது.',
