      infoBaseHarbourWord: 'அடிப்படைத் துறை',
      infoBaseHarbourBodyWord: 'GPS நிலையை வழங்கும் வரை ஒவ்வொரு இட அளவீடும் இந்தத் துறையுடனே இணைக்கப்படுகிறது.',
      infoAcceptanceWord: 'ஏற்றுக்கொள்ளும் சோதனை',
      infoAcceptanceBodyWord: 'கேள்விப் பிரகடனத்தின் எட்டு திறன்களும் அனைத்து {n} மொழிகளிலும் உண்மையான கேள்விகளாக ஏற்கனவே ஏற்றப்பட்டுள்ளன. ஒவ்வொன்றும் நீங்கள் தட்டச்சு செய்வது போலவே அதே பொயில் வழியாகச் செல்கிறது — எனவே ஒன்றைத் தட்டுவது மொழி கண்டறிதல், நோக்கப் பகுப்பாய்வு, பட்டியல் தேர்வு மற்றும் பொதுச்செயல் ஆகியவற்றின் உண்மையான சோதனை, நிரலாக்கப்பட்ட பதில் அல்ல.',
      infoOpenChatWord: '{lang} மொழியில் உரையாடலைத் திற',
      infoSafetyWord: 'பாதுகாப்பு தரநிலை & பொறுப்புடைய AI',
      infoSafetyBodyWord: 'ORCA முடிவு ஆதரவளிக்கிறது. அது ஒருபோதும் பாதுகாப்பை உறுதிப்படுத்துவதில்லை, அதேபோது அதிகாரப்பூர்வ எச்சரிக்கையை ஒருபோதும் முற்றிலும் மறுக்காது. காட்டுவதற்கு முன் ஒரு பிரத்யேக மதிப்பாய்வுக் கருவி ஒவ்வொரு பதிலையும் மீண்டும் வாசிக்கிறது, அதிக நம்பிக்கையான சொற்றொடர்களை நீக்குகிறது, எந்த ORANGE அல்லது RED எச்சரிக்கையையும் உயர்த்துகிறது, மேலும் அதை IMD, INCOIS மற்றும் துறை உரிமையாளர் எச்சரிக்கைகளுடன் இணைக்கிறது. கப்பலின் முடிவாக தோட்டி எடுத்த முடிவே மட்டும்.',
      apkTitleWord: 'ORCA உருவாக்கம் & செயல்விளக்கக் கூடம்',
      apkSubtitleWord: 'ஒரு TypeScript முக்கிய எந்திரம் · இணைய கிளையென்ட் + Android APK',
      apkTabBuildWord: 'APK உருவாக்கம்',
      apkTabEngineWord: 'எந்திரம் & API',
      apkTabStructureWord: 'கோப்புறை அமைப்பு',
      apkTabDemoWord: '3-நிமிட செயல்விளக்கக் குறிப்பு',
      apkStep1Word: '1. Expo EAS மேகக் கட்டுதலுடன் சுதந்திர APK',
      apkStep1BodyWord: 'EAS நேரடியாக நிறுவப்படக்கூடிய APK க்கான ஒரு பதிவிறக்க இணைப்பையும் QR குறியீட்டையும் அச்சிடுகிறது — Android Studio தேவையில்லை, உள்ளூர் SDK தேவையில்லை, பெறும் தொலைபேசியில் எதையும் அமைக்க வேண்டியதில்லை.',
      apkStep2Word: '2. Expo Go உடன் உண்மையான தொலைபேசியில் உடனே சோதனை',
      apkStep3Word: '3. APK ஐ வழங்கப்பட்ட எந்திரத்துடன் இணைத்தல்',
      apkStep3BodyWord: 'முகவரி சரியாக ஒரே இடத்தில் உள்ளது, mobile/src/services/api.js, மேலும் அது முதலில் ஒரு சூழல் மாற்றியைப் படிக்கிறது:',
      apkStep3Body2Word: 'உருவாக்க நேர இலக்குக்காக, eas.json இல் EXPO_PUBLIC_ORCA_API=https://your-host என அமைக்கவும்.',
      apkStep3NoteWord: 'எந்திரம் கிடைக்காவிட்டால் செயலி தெளிவாகச் சொல்கிறது — அது ஒருபோதும் கற்பனையான முன்னறிவிப்பைச் சேர்ப்பதில்லை.',
      apkEngineHeadingWord: 'முக்கிய எந்திரத்தை இயக்குதல்',
      apkEngineKeyNoteWord: 'GEMINI_API_KEY என்பது விருப்பத்தேர்வு. அது இல்லாவிட்டாலும் நிர்ணயமான இயந்திரம் ஒவ்வொரு பதிலுக்கும் திட்டமிடுகிறது, காரணம் விளக்குகிறது, இணைக்கிறது மற்றும் சரிபார்க்கிறது.',
