      infoRosterBodyWord: 'ଜଣେ ପ୍ଲାନର ପ୍ରତ୍ୟେକ ପ୍ରଶ୍ନକୁ କାର୍ଯ୍ୟ ଗ୍ରାଫରେ ବିଭଜନ କରି ଏହି ବିଶେଷଜ୍ଞଙ୍କ ମଧ୍ୟରୁ ଏକ ଭାଗ ବାଛନ୍ତି। ସେମାନେ ଏକ ସାଧାର୍ଣ ବ୍ଲ୍ୟାକବୋର୍ଡରେ ଟାଇପ୍ ହୋଇଥିବା ଫଳାଫଳ ପ୍ରକାଶ କରନ୍ତି, ଯେକୌଁସି ଏଜେଣ୍ଟ ସହକର୍ମୀରୁ ସାହାଯ୍ୟ ପାଇଁ ଅନୁରୋଧ କରିପାରିବ, ଏବଂ ଏଜଣ ସମୀକ୍ଷକ ଦେଖାଇବା ପୂର୍ବରୁ ସଂଶ୍ଳେଷିତ ଉତ୍ତର ସମୀକ୍ଷା କରେ।',
