      infoBaseHarbourWord: 'ମୂଳ ବନ୍ଦର',
      infoBaseHarbourBodyWord: 'GPS ଅବସ୍ଥାନ ଦେବା ପର୍ଯ୍ୟନ୍ତ ପ୍ରତ୍ୟେକ ସ୍ଥାନିକ ଗଣନା ଏହି ବନ୍ଦର ସହିତ ଯୋଡ଼ାଯାଇଛି।',
