      infoSafetyWord: 'ସୁରକ୍ଷା ମାନକ ଓ ଦାୟିତ୍ୱ AI',
      infoSafetyBodyWord: 'ORCA ନିଷ୍ପତ୍ତି ସହାୟତା ଦେଇଥାଏ। ଏହା କେବେ ସୁରକ୍ଷାର ନିଶ୍ଚୟତା ଦେଇନାହିଁ, ଏବଂ କେବେ କୌଣସି ସରକାରୀ ସତର୍କତାକୁ ଅନୁଲୋମନ କରେ ନାହିଁ। ଦେଖାଇବା ପୂର୍ବରୁ ଏକ ନିବେଦିତ ସମୀକ୍ଷକ ଏଜେଣ୍ଟ ପ୍ରତ୍ୟେକ ଉତ୍ତର ପୁନଃ ପଢ଼େ, ଅତି ଆତ୍ମବିଶ୍ୱାସକାର ବାକ୍ୟ ହଟାଏ, ORANGE କିମ୍ବା RED ସତର୍କତାକୁ ଉଚ୍ଚରିଗମ କରେ, ଏବଂ ତାହାକୁ IMD, INCOIS ଓ ବନ୍ଦର କର୍ତ୍ତୃପକ୍ଷର ସତର୍କତା ସହିତ ଯୋଡ଼ାଏ। ଜହାଜର ନିଷ୍ପତ୍ତି ମାଲିକର ହିଁରେ ରହେ।',
      apkTitleWord: 'ORCA ବିଲ୍ଡ ଓ ପ୍ରଦର୍ଶନ କେନ୍ଦ୍ର',
      apkSubtitleWord: 'ଏକ TypeScript ଏଜେଣ୍ଟ ଇଞ୍ଜିନ · ଓୱେବ କ୍ଲାଏଣ୍ଟ + Android APK',
      apkTabBuildWord: 'APK ବିଲ୍ଡ',
