      infoNoApiKeyWord: 'GEMINI_API_KEY ਸੈੱਟ ਨਹੀਂ ਕੀਤਾ ਗਿਆ। ਇਸ ਤੋਂ ਬਿਨਾਂ ਵੀ ORCA ਪੂਰੀ ਤਰ੍ਹਾਂ ਕੰਮ ਕਰਦਾ ਹੈ — ਚੋਣਵੀਂ ਮਾਡਲ ਸਿਰਫ਼ ਯੋਜਨਾ ਦਾ ਤਰਕ ਅਤੇ ਜਵਾਬ ਦੀ ਭਾਸ਼ਾ ਮੁੜ ਲਿਖਦਾ ਹੈ, ਅਤੇ ਉਹ ਕਦੇ ਵੀ ਕੋਈ ਸੁਰੱਖਿਆ-ਅਹਿਮ ਏਜੰਟ ਨਹੀਂ ਜੋੜ ਕੇ ਹਟਾ ਸਕਦਾ।',
      infoRosterWord: 'ਏਜੰਟ ਸੂਚੀ ({n})',
      infoRosterBodyWord: 'ਇੱਕ ਪਲੈਨਰ ਹਰ ਸਵਾਲ ਨੂੰ ਕੰਮ-ਗ੍ਰਾਫ ਵਿੱਚ ਵੰਡਦਾ ਹੈ ਅਤੇ ਇਨ੍ਹਾਂ ਮਾਹਰਾਂ ਵਿੱਚੋਂ ਇੱਕ ਹਿੱਸਾ ਚੁਣਦਾ ਹੈ। ਉਹ ਇੱਕ ਸਾਂਝੀ ਬਲੈਕਬੋਰਡ ’ਤੇ ਟਾਈਪ ਕੀਤੇ ਨਤੀਜੇ ਪ੍ਰਕਾਸ਼ਿਤ ਕਰਦੇ ਹਨ, ਕੋਈ ਵੀ ਏਜੰਟ ਸਾਥੀ ਤੋਂ ਮਦਦ ਮੰਗ ਸਕਦਾ ਹੈ, ਅਤੇ ਇੱਕ ਸਮੀਖਿਅਕ ਦਿਖਾਉਣ ਤੋਂ ਪਹਿਲਾਂ ਸੰਸਲਿਟ ਜਵਾਬ ਦੀ ਸਮੀਖਿਆ ਕਰਦਾ ਹੈ।',
