      infoAcceptanceWord: 'ਸਵੀਕਾਰਤਾ ਜਾਂਚ',
      infoAcceptanceBodyWord: 'ਸਮੱਸਿਆ ਬਿਆਨ ਦੀਆਂ ਅੱਠ ਸਮਰੱਥਾਵਾਂ ਸਾਰੀਆਂ {n} ਭਾਸ਼ਾਵਾਂ ਵਿੱਚ ਪਹਿਲਾਂ ਹੀ ਅਸਲੀ ਸਵਾਲਾਂ ਵਜੋਂ ਲੋਡ ਕੀਤੀਆਂ ਹਨ। ਹਰੇਕ ਉਹੀ ਪਾਈਪਲਾਈਨ ਤੋਂ ਲੰਘਦੀ ਹੈ ਜਿਸ ਤੋਂ ਤੁਸੀਂ ਕੁਝ ਵੀ ਟਾਈਪ ਕਰਦੇ ਹੋ — ਇਸ ਲਈ ਕਿਸੇ ਇੱਕ ਨੂੰ ਟੈਪ ਕਰਨਾ ਭਾਸ਼ਾ ਪਛਾਣ, ਇੰਟੈਂਟ ਪਾਰਸਿੰਗ, ਸੂਚੀ ਚੋਣ ਅਤੇ ਸੰਸਥਾਪਨ ਦੀ ਅਸਲੀ ਜਾਂਚ ਹੈ, ਲਿਖਤੀ ਜਵਾਬ ਨਹੀਂ।',
      infoOpenChatWord: '{lang} ਵਿੱਚ ਗੱਲਬਾਤ ਖੋਲ੍ਹੋ',
      infoSafetyWord: 'ਸੁਰੱਖਿਆ ਮਿਆਰਕ ਅਤੇ ਜ਼ਿੰਮੇਵਾਰ AI',
      infoSafetyBodyWord: 'ORCA ਫ਼ੈਸਲਾ ਸਹਾਇਤਾ ਦਿੰਦਾ ਹੈ। ਇਹ ਕਦੇ ਸੁਰੱਖਿਆ ਦੀ ਗਰੰਟੀ ਨਹੀਂ ਦਿੰਦਾ, ਅਤੇ ਕਦੇ ਕੋਈ ਅਧਿਕਾਰਤ ਚੇਤਾਵਨੀ ਨੂੰ ਵੀ ਰੱਦ ਨਹੀਂ ਦਿੰਦਾ। ਦਿਖਾਉਣ ਤੋਂ ਪਹਿਲਾਂ ਇੱਕ ਵਿਸ਼ੇਸ਼ ਸਮੀਖਿਅਕ ਏਜੰਟ ਹਰ ਜਵਾਬ ਨੂੰ ਮੁੜ ਪੜ੍ਹਦਾ ਹੈ, ਬਹੁਤ ਆਤਮਵਿਸ਼ਵਾਸ ਵਾਲੇ ਵਾਕ ਹਟਾਉਂਦਾ ਹੈ, ORANGE ਜਾਂ RED ਚੇਤਾਵਨੀ ਨੂੰ ਉੱਚਾ ਦਿਖਾਉਂਦਾ ਹੈ, ਅਤੇ ਉਸ ਨੂੰ IMD, INCOIS ਅਤੇ ਬੰਦਰ ਅਥਾਰਟੀ ਦੀਆਂ ਚੇਤਾਵਨੀਆਂ ਨਾਲ ਜੋੜਦਾ ਹੈ। ਜਹਾਜ਼ ਦਾ ਫ਼ੈਸਲਾ ਮਾਲਕ ਦਾ ਹੀ ਰਹਿੰਦਾ ਹੈ।',
